stringarraysubstr_replace arraystringstring arraystringreplace arrayintoffset arrayintnulllength&null;
substr_replace sostituisce una copia di string delimitata dai parametri offset e (opzionalmente) length con la stringa indicata in replace.

&reftitle.returnvalues;


 Viene restituita la stringa risultante. Se string è un
 array, viene restituito un array.

  &reftitle.examples;



    Esempi semplici di substr_replace


<?php
$var = 'ABCDEFGH:/MNRPQR/';
echo "Originale: $var<hr />\n";

/* Questi due esempi sostituiscono tutto $var con 'bob'. */
echo substr_replace($var, 'bob', 0) . "<br />\n";
echo substr_replace($var, 'bob', 0, strlen($var)) . "<br />\n";

/* Inserisce 'bob' proprio all'inizio di $var. */
echo substr_replace($var, 'bob', 0, 0) . "<br />\n";

/* I due esempi seguenti sostituiscono 'MNRPQR' in $var con 'bob'. */
echo substr_replace($var, 'bob', 10, -1) . "<br />\n";
echo substr_replace($var, 'bob', -7, -1) . "<br />\n";

/* Elimina 'MNRPQR' da $var. */
echo substr_replace($var, '', 10, -1) . "<br />\n";
?>








     Uso di substr_replace per sostituire più stringhe
     contemporaneamente



<?php
$input = array('A: XXX', 'B: XXX', 'C: XXX');

// Un caso semplice: sostituisce XXX in ogni stringa con YYY.
echo implode('; ', substr_replace($input, 'YYY', 3, 3))."\n";

// Un caso più complicato in cui ogni sostituzione è diversa.
$replace = array('AAA', 'BBB', 'CCC');
echo implode('; ', substr_replace($input, $replace, 3, 3))."\n";

// Sostituisce ogni volta un numero diverso di caratteri.
$length = array(1, 2, 3);
echo implode('; ', substr_replace($input, $replace, 3, $length))."\n";
?>


    &example.outputs;


A: YYY; B: YYY; C: YYY
A: AAA; B: BBB; C: CCC
A: AAAXX; B: BBBX; C: CCC
